const instance = "Agent_Calendar";
const now = DateTime.now().setZone('America/Recife');
const due = [];

for (const item of $input.all()) {
  const ev = item.json;

  if (!ev || ev.status === 'cancelled') continue;

  const start = ev.start || {};
  if (!start.dateTime) continue;

  const startDt = DateTime.fromISO(start.dateTime)
    .setZone('America/Recife');

  if (!startDt.isValid) continue;

  const reminderAt = startDt.minus({ minutes: 30 });

  if (now < reminderAt || now >= startDt) continue;

  const title = ev.summary || 'Compromisso';
  const description = ev.description || '';

  due.push({
    json: {
      eventId: String(ev.id),
      occurrenceStart: startDt.toISO(),
      summary: title,
      description: description,
      category: '',
      instance: instance,
      eventDate: startDt.toFormat("dd/LL/yyyy"),
      eventTime: startDt.toFormat("HH:mm"),
      text: `${title} começa às ${startDt.toFormat('HH:mm')}.`,
    },
  });
}

return due;

