const item = $input.item.json;

// Identifica onde está o resultado da IA
let data = item.output ?? item;

// Se a saída vier como texto, converte para objeto JSON
if (typeof data === 'string') {
  // Remove cercas Markdown, caso existam
  data = data
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();

  data = JSON.parse(data);
}

// Retorna os campos separados e preserva os dados originais
return {
  json: {
    ...item,
    category: data.category,
    briefing: data.briefing,
    whatsapp_text: data.whatsapp_text,
    visual_prompt: data.visual_prompt,
  },
};

